reference.setup:
{
    ref_curve <- function(t, p) p[1] * exp(-exp((p[2] * exp(1)/p[1]) * (p[3] - t) + 
        1))
    ref_jacobian <- function(t, p) {
        sapply(1:3, function(j) {
            h <- 1e-06
            at <- function(k) {
                q <- p
                q[j] <- p[j] + k * h
                ref_curve(t, q)
            }
            (at(-2) - 8 * at(-1) + 8 * at(1) - at(2))/(12 * h)
        })
    }
    ref_runs <- function(s) {
        n1 <- sum(s > 0)
        n2 <- sum(s < 0)
        r <- 1 + sum(s[-1] != s[-length(s)])
        m <- 2 * n1 * n2/(n1 + n2) + 1
        v <- (m - 1) * (m - 2)/(n1 + n2 - 1)
        z <- (r - m)/sqrt(v)
        list(ran = TRUE, n_runs = r, n_pos = n1, n_neg = n2, z = z, p = 2 * pnorm(-abs(z)))
    }
    ref_optimum <- function(t, y, start = NULL) {
        best <- c(Inf, NA, NA, NA)
        if (!is.null(start)) 
            best <- c(0, start)
        if (is.null(start)) {
            span <- max(t) - min(t)
            lambda_grid <- seq(min(t) - span * 0.5, max(t) + span * 0.5, length.out = 21)
            yr <- max(y) - min(y)
            ord <- order(t)
            d <- diff(y[ord])/diff(t[ord])
            slope <- max(d[is.finite(d)], yr/span)
            mumax_grid <- exp(seq(log(slope/50), log(slope * 5), length.out = 25))
            a_grid <- max(y) * c(1, 1.1, 1.3)
            for (lambda in lambda_grid) for (mumax in mumax_grid) for (a in a_grid) {
                rss <- sum((y - ref_curve(t, c(a, mumax, lambda)))^2)
                if (is.finite(rss) && rss < best[1]) 
                  best <- c(rss, a, mumax, lambda)
            }
        }
        p <- unname(best[2:4])
        rss <- function(p) sum((y - ref_curve(t, p))^2)
        lambda_lm <- 0.001
        for (it in 1:1000) {
            J <- ref_jacobian(t, p)
            A <- crossprod(J)
            step <- tryCatch(unname(drop(solve(A + lambda_lm * diag(diag(A)), crossprod(J, 
                y - ref_curve(t, p))))), error = function(e) NULL)
            if (is.null(step) || any(!is.finite(step))) {
                lambda_lm <- lambda_lm * 10
                if (lambda_lm > 1e+12) 
                  break
                next
            }
            if (rss(p + step) <= rss(p)) {
                p <- p + step
                lambda_lm <- lambda_lm/10
            }
            else {
                lambda_lm <- lambda_lm * 10
            }
            if (max(abs(step)/pmax(abs(p), 1e-08)) < 1e-14 || lambda_lm > 1e+12) 
                break
        }
        for (it in 1:5) {
            J <- ref_jacobian(t, p)
            step <- tryCatch(unname(drop(qr.coef(qr(J), y - ref_curve(t, p)))), error = function(e) NULL)
            if (is.null(step) || any(!is.finite(step))) 
                break
            p <- p + step
        }
        p
    }
    ref_quantity <- function(value, se, t) {
        list(value = value, se = se, lower = value - t * se, upper = value + t * 
            se)
    }
    run_gc <- function(t, y) {
        n <- length(t)
        p <- ref_optimum(t, y)
        J <- ref_jacobian(t, p)
        A <- crossprod(J)
        Ainv <- solve(A)
        fitted <- ref_curve(t, p)
        resid <- y - fitted
        df <- n - 3
        ss <- sum(resid^2)
        s2 <- ss/df
        se <- sqrt(s2 * diag(Ainv))
        tcrit <- qt(0.975, df)
        ord <- order(t)
        signs <- sign(resid[ord])
        grid <- seq(min(t), max(t), length.out = 100)
        G <- ref_jacobian(grid, p)
        var_fit <- vapply(seq_along(grid), function(i) drop(G[i, ] %*% Ainv %*% G[i, 
            ]), 0) * s2
        fit_grid <- ref_curve(grid, p)
        doubling_grad <- c(0, -log(2)/p[2]^2, 0)
        doubling_se <- sqrt(drop(doubling_grad %*% Ainv %*% doubling_grad) * s2)
        tau_grad <- c(1/p[2], -p[1]/p[2]^2, 1)
        tau_se <- sqrt(drop(tau_grad %*% Ainv %*% tau_grad) * s2)
        list(n = n, ran = TRUE, asymptote = ref_quantity(p[1], se[1], tcrit), growth_rate = ref_quantity(p[2], 
            se[2], tcrit), lag = ref_quantity(p[3], se[3], tcrit), doubling_time = ref_quantity(log(2)/p[2], 
            doubling_se, tcrit), exponential_end = ref_quantity(p[3] + p[1]/p[2], 
            tau_se, tcrit), df = df, ss = ss, syx = sqrt(s2), r2 = 1 - ss/sum((y - 
            mean(y))^2), x = t[ord], y = y[ord], fitted = fitted[ord], residual = resid[ord], 
            runs = ref_runs(signs[signs != 0]), band = list(x = grid, fit = fit_grid, 
                confidence_lower = fit_grid - tcrit * sqrt(var_fit), confidence_upper = fit_grid + 
                  tcrit * sqrt(var_fit), prediction_lower = fit_grid - tcrit * sqrt(var_fit + 
                  s2), prediction_upper = fit_grid + tcrit * sqrt(var_fit + s2)))
    }
}

